<?php
use App\Models\Permission; use App\Models\PublicPage; use App\Models\User; use Illuminate\Foundation\Testing\RefreshDatabase; use Inertia\Testing\AssertableInertia as Assert;
uses(RefreshDatabase::class);
function pageAdmin(): User { $u=User::factory()->create(['email_verified_at'=>now()]); foreach([['view_admin','View Admin'],['manage_public_pages','Manage Public Pages'],['publish_public_pages','Publish Public Pages']] as [$name,$label]){$p=Permission::firstOrCreate(['name'=>$name],['label'=>$label,'group_name'=>'Content','description'=>$label]);$u->permissions()->syncWithoutDetaching([$p->id]);} return $u; }
it('shows only active published pages publicly', function(){ $published=PublicPage::factory()->published()->create(['slug'=>'about-us']); PublicPage::factory()->create(['slug'=>'draft-page']); $this->get('/about-us')->assertOk()->assertInertia(fn(Assert $p)=>$p->component('PublicPages/Show')->where('publicPage.slug','about-us')); $this->get('/draft-page')->assertNotFound(); });
it('protects public page administration', function(){ $this->get('/admin/public-pages')->assertRedirect('/login'); $this->actingAs(pageAdmin())->get('/admin/public-pages')->assertOk(); });
it('creates a published page and reserves application slugs', function(){ $u=pageAdmin(); $this->actingAs($u)->post('/admin/public-pages',['title'=>'About Us','slug'=>'about-us','page_type'=>'standard','status'=>'published','is_active'=>true,'sort_order'=>10,'navigation_locations'=>['header']])->assertRedirect('/admin/public-pages'); expect(PublicPage::where('slug','about-us')->firstOrFail()->isPublished())->toBeTrue(); $this->actingAs($u)->post('/admin/public-pages',['title'=>'Blog','slug'=>'blog','page_type'=>'standard','status'=>'draft','is_active'=>true,'sort_order'=>10])->assertSessionHasErrors('slug'); });
it('shares published navigation pages', function(){ PublicPage::factory()->published()->create(['title'=>'About','slug'=>'about','navigation_locations'=>['header','footer_company'],'sort_order'=>1]); $this->get('/')->assertInertia(fn(Assert $p)=>$p->has('public_page_navigation.header',1)->where('public_page_navigation.header.0.href','/about')); });
